79:         SiloDeposits calldata beanEthDeposits,
80:         SiloDeposits calldata beanWstEthDeposits,
81:         SiloDeposits calldata bean3CrvDeposits,
82:         SiloDeposits calldata urBeanDeposits,
83:         SiloDeposits calldata urBeanLpDeposits
84:     ) external {
85:         // initialize beanDeposits.
86:         reseedSiloDeposit(beanDeposits);
87: 
88:         // initialize beanEthDeposits.
89:         reseedSiloDeposit(beanEthDeposits);
90: 
91:         // initialize beanWstEthDeposits.
92:         reseedSiloDeposit(beanWstEthDeposits);
93: 
94:         // initialize beanStableDeposits.
95:         reseedSiloDeposit(bean3CrvDeposits);
96: 
97:         // initialize urBeanDeposits.
98:         reseedSiloDeposit(urBeanDeposits);
99: 
100:         // initialize urBeanLpDeposits.
101:         reseedSiloDeposit(urBeanLpDeposits);
102:     }
103: 
104:     /**
105:      * @notice reseed the silo deposit for a given token.
106:      * @param siloDeposit The silo deposit data
107:      * @dev all deposits and accounts are mown to the current season.
108:      */
109:     function reseedSiloDeposit(SiloDeposits calldata siloDeposit) internal {
110:         uint256 totalCalcDeposited;
111:         uint256 totalCalcDepositedBdv;
112:         uint256 stalkIssuedPerBdv = s.sys.silo.assetSettings[siloDeposit.token].stalkIssuedPerBdv;
113:         for (uint256 i; i < siloDeposit.siloDepositsAccount.length; i++) {
114:             AccountSiloDeposits memory deposits = siloDeposit.siloDepositsAccount[i];
115:             uint128 totalBdvForAccount;
116:             uint256 accountStalk;
117:             for (uint256 j; j < deposits.dd.length; j++) {
118:                 // verify that depositId is valid.
119:                 int96 stem = deposits.dd[j].stem;
120:                 require(siloDeposit.stemTip >= stem, "ReseedSilo: INVALID_STEM");
121:                 uint256 depositId = LibBytes.packAddressAndStem(siloDeposit.token, stem);
122: 
123:                 // add deposit to account. Add to depositIdList.
124:                 s.accts[deposits.accounts].deposits[depositId].amount = deposits.dd[j].amount;
125:                 s.accts[deposits.accounts].deposits[depositId].bdv = deposits.dd[j].bdv;
126:                 s.accts[deposits.accounts].depositIdList[siloDeposit.token].push(depositId);
127: 
128:                 // increment totalBdvForAccount by bdv of deposit:
129:                 totalBdvForAccount += deposits.dd[j].bdv;
130: 
131:                 // increment by grown stalk of deposit.
132:                 accountStalk += uint96(siloDeposit.stemTip - stem) * deposits.dd[j].bdv;
133: 
134:                 // increment totalCalcDeposited and totalCalcDepositedBdv.
135:                 totalCalcDeposited += deposits.dd[j].amount;
136:                 totalCalcDepositedBdv += deposits.dd[j].bdv;
137: 
138:                 // emit events.
139:                 emit AddDeposit(
140:                     deposits.accounts,
141:                     siloDeposit.token,
142:                     stem,
143:                     deposits.dd[j].amount,
144:                     deposits.dd[j].bdv
145:                 );
146:                 emit TransferSingle(
147:                     deposits.accounts, // operator
148:                     address(0), // from
149:                     deposits.accounts, // to
150:                     depositId, // depositID
151:                     deposits.dd[j].amount // token amount
152:                 );
153:             }
154:             // update mowStatuses for account and token.
155:             s.accts[deposits.accounts].mowStatuses[siloDeposit.token].bdv = totalBdvForAccount;
156:             s.accts[deposits.accounts].mowStatuses[siloDeposit.token].lastStem = siloDeposit
157:                 .stemTip;
158: 
159:             // increment stalkForAccount by the stalk issued per BDV.
160:             // placed outside of loop for gas effiency.
161:             accountStalk += stalkIssuedPerBdv * totalBdvForAccount;
162: 
163:             // set stalk for account.
164:             s.accts[deposits.accounts].stalk = accountStalk;
165:         }
166: 
167:         // verify that the total deposited and total deposited bdv are correct.
168:         require(
169:             totalCalcDeposited == siloDeposit.totalDeposited,
170:             "ReseedSilo: INVALID_TOTAL_DEPOSITS"
171:         );
172:         require(
173:             totalCalcDepositedBdv == siloDeposit.totalDepositedBdv,
174:             "ReseedSilo: INVALID_TOTAL_DEPOSITED_BDV"
175:         );
176: 
177:         // set global state
178:         s.sys.silo.balances[siloDeposit.token].deposited = siloDeposit.totalDeposited;
179:         s.sys.silo.balances[siloDeposit.token].depositedBdv = siloDeposit.totalDepositedBdv;
180:     }
181: }
